&lt;p&gt;&lt;span class=&quot;TextRun SCXW182919787 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SpellingErrorV2Themed SCXW182919787 BCX0&quot; data-ccp-charstyle=&quot;normaltextrun&quot; data-ccp-charstyle-defn=&quot;{&amp;quot;ObjectId&amp;quot;:&amp;quot;db2d2cc1-08b2-4ddd-a884-b285c3400554|43&amp;quot;,&amp;quot;ClassId&amp;quot;:1073872969,&amp;quot;Properties&amp;quot;:[469775450,&amp;quot;normaltextrun&amp;quot;,201340122,&amp;quot;1&amp;quot;,134233614,&amp;quot;true&amp;quot;,469778129,&amp;quot;normaltextrun&amp;quot;,335572020,&amp;quot;1&amp;quot;,469778324,&amp;quot;Default Paragraph Font&amp;quot;]}&quot;&gt;unybrands&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW182919787 BCX0&quot; data-ccp-charstyle=&quot;normaltextrun&quot;&gt; is an equal opportunity employer and considers all applicants for employment without any regard to race, skin color, religion, gender identity, sexual orientation, and age. Nor are applicants discriminated against based on disability or protected classes. &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW182919787 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
